def _buttons(page: int):
    rows = []
    if page > 0:
        rows.append([Button.inline("⬅️ قبلی", PREFIX + f"page:{page-1}".encode())])
    if page + 1 < len(PAGES):
        rows.append([Button.inline("بعدی ➡️", PREFIX + f"page:{page+1}".encode())])
    rows.append([Button.inline("📑 فهرست راهنما", PREFIX + b"index")])
    rows.append([Button.inline("🏠 پنل مدیریت", b"rep:home")])
    return rows


def index_text() -> str:
    return "📘 **راهنمای مدیریت ربات نمایندگی**\n\nموضوع موردنظر را انتخاب کنید:" 


def index_buttons():
    rows = []
    for i, (title, _) in enumerate(PAGES):
        rows.append([Button.inline(title, PREFIX + f"page:{i}".encode())])
    rows.append([Button.inline("🏠 پنل مدیریت", b"rep:home")])
    return rows


async def render(page: int = 0):
    page = max(0, min(page, len(PAGES) - 1))
    title, body = PAGES[page]
    text = f"📘 **راهنمای مدیریت ربات نمایندگی**\n\n{title}\n\n{body}\n\n📖 صفحه {page + 1} از {len(PAGES)}"
    return text, _buttons(page)
